package android.database;import java.util.*;public class Cursor implements AutoCloseable{final List<Object[]> rows;int position=-1;public Cursor(List<Object[]> values){rows=values;}public boolean moveToFirst(){position=0;return !rows.isEmpty();}public boolean moveToNext(){return ++position<rows.size();}public String getString(int i){return (String)rows.get(position)[i];}public long getLong(int i){return ((Number)rows.get(position)[i]).longValue();}public void close(){}}
